  if(method==='POST'){
    check(object(value),'INVALID_CRYPTOWORTH_REQUEST','Provide the original reviewed request.');
    if(Object.hasOwn(value,'workspaceId'))check(value.workspaceId===controller.workspaceId,'CRYPTOWORTH_WORKSPACE_CHANGED','This local address now belongs to a different accounting workspace. Reopen its saved drafts before continuing.',409);
    const {workspaceId,...request}=value;value=request;
  }
  if(parts.length===2&&method==='GET')return {value:controller.view()};
  if(parts.length===3&&parts[2]==='source'&&method==='GET')return {value:await controller.source(query)};
  if(parts.length===4&&parts[2]==='templates'&&parts[3]==='inspect'&&method==='POST')return {value:inspectCryptoworthTemplate(value.file,{delimiter:value.delimiter})};
  if(parts[2]==='profiles'){
    if(parts.length===3&&method==='POST')return {value:await controller.createProfile(value)};
    if(parts.length===4&&parts[3]==='preview'&&method==='POST')return {value:await controller.previewProfile(value)};
    if(parts.length===4&&method==='GET')return {value:await controller.profileDetail(parts[3])};
    if(parts.length===6&&parts[4]==='download'&&method==='GET')return {file:await controller.profileFile(parts[3],parts[5])};
  }
  if(parts[2]==='plans'){
    if(parts.length===3&&method==='POST')return {value:await controller.createPlan(value)};
    if(parts.length===4&&parts[3]==='preview'&&method==='POST')return {value:await controller.previewPlan(value,query)};
    const planId=parts[3];
    if(planId&&parts.length===4&&method==='GET')return {value:await controller.detail(planId)};
    if(planId&&parts.length===5){
      if(parts[4]==='rows'&&method==='GET')return {value:await controller.rows(planId,query)};
      if(parts[4]==='captures'&&method==='POST')return {value:await controller.createCapture(planId,value)};
      if(parts[4]==='returns'&&method==='POST')return {value:await controller.saveReturn(planId,value)};
      if(parts[4]==='rollbacks'&&method==='POST')return {value:await controller.rollback(planId,value)};
      if(parts[4]==='packet'&&method==='GET')return {file:await controller.packet(planId)};
    }
    if(planId&&parts.length===6){
      if(parts[4]==='download'&&method==='GET')return {file:await controller.file(planId,parts[5],query)};
      if(parts[4]==='captures'&&parts[5]==='preview'&&method==='POST')return {value:await controller.previewCapture(planId,value,query)};
      if(parts[4]==='returns'&&parts[5]==='preview'&&method==='POST')return {value:await controller.previewReturn(planId,value)};
      if(parts[4]==='captures'&&method==='GET')return {value:await controller.captureDetail(planId,parts[5])};
      if(parts[4]==='returns'&&method==='GET')return {value:await controller.returnDetail(planId,parts[5])};
    }
    if(planId&&parts.length===7&&parts[4]==='captures'&&parts[6]==='rows'&&method==='GET')return {value:await controller.captureRows(planId,parts[5],query)};
  }
  if(parts.length===4&&parts[2]==='packets'&&method==='POST'){
    if(parts[3]==='inspect')return {value:await controller.inspectPacket(value)};
    if(parts[3]==='receive')return {value:await controller.receivePacket(value)};
  }
  check(false,'NOT_FOUND','This Cryptoworth receiving operation was not found.',404);
}

// MIT. Managed launch for the original merchant accounting and OAuth owners.
import { constants } from 'node:fs';
import { open, lstat, realpath } from 'node:fs/promises';
import { dirname, basename, join, resolve, isAbsolute } from 'node:path';
import { randomUUID } from 'node:crypto';
import { inspectOpenApiLaunch } from '../../sf61-openapi-seller-import/workspace/managed-launch.mjs';
import { identity, digest, fault } from '../../sf30-seller-sdk/postgres/publisher/files.mjs';
import { plain, hex, envName } from '../../sf30-seller-sdk/oauth-connections/profile.mjs';
import { quickbooksSource, quickBooksSelectionSummary } from '../../sf30-seller-sdk/oauth-connections/quickbooks.mjs';
import { xeroSource, xeroSelectionSummary } from '../../sf30-seller-sdk/oauth-connections/xero.mjs';
import { readAccountingSelections, openAccountingConnections } from './connections-workspace.mjs';
import { inspectAccountingWorkspaceBinding } from './binding.mjs';

export const ACCOUNTING_MANAGED_SCHEMA = 'stellar-forge.managed-accounting-binding.v1';
export const ACCOUNTING_STARTUP_SCHEMA = 'stellar-forge.managed-accounting-startup.v1';
const need = (ok, code, message, status = 409) => { if (!ok) throw fault(code, message, status); };
const absolute = value => {
  need(typeof value === 'string' && isAbsolute(value) && resolve(value) === value && value !== '/' &&
    !/[\x00-\x1f\x7f]/.test(value), 'ACCOUNTING_MANAGED_PATH', 'Use a canonical original accounting path.', 400);
  return value;
};
const optionalPaths = ['outboxDir', 'proofDir', 'termsFile', 'recoveredDir', 'recoveryStateRoot', 'recoveryBackupRoot'];
const optionalEnvs = ['rpcProxyEnv', 'recoveryPassEnv', 'deliverySecretEnv'];
const permitted = ['directory', 'port', 'connectionsFile', 'selectionDirectory', 'allowLoopbackOAuth',
  'recoveryStartPaused', ...optionalPaths, ...optionalEnvs];
function settings(raw) {
  need(plain(raw) && Object.keys(raw).every(name => permitted.includes(name)),
    'ACCOUNTING_MANAGED_OPTIONS', 'Use the original managed accounting options.', 400);
  const value = { directory: absolute(raw.directory), port: raw.port ?? 0,
    connectionsFile: raw.connectionsFile ? absolute(raw.connectionsFile) : null,
    selectionDirectory: raw.selectionDirectory ? absolute(raw.selectionDirectory) :
      join(dirname(raw.directory), basename(raw.directory) + '-connections'),
    allowLoopbackOAuth: raw.allowLoopbackOAuth === true, recoveryStartPaused: raw.recoveryStartPaused === true };
  need(Number.isInteger(value.port) && value.port >= 0 && value.port <= 65535 &&
    (raw.allowLoopbackOAuth === undefined || typeof raw.allowLoopbackOAuth === 'boolean') &&
    (raw.recoveryStartPaused === undefined || typeof raw.recoveryStartPaused === 'boolean'),
  'ACCOUNTING_MANAGED_OPTIONS', 'Use a valid local listener and explicit recovery options.', 400);
  for (const name of optionalPaths) if (raw[name]) value[name] = absolute(raw[name]);
  for (const name of optionalEnvs) if (raw[name]) {
    need(envName(raw[name]), 'ACCOUNTING_MANAGED_OPTIONS', 'Use a named host environment reference.', 400);
    value[name] = raw[name];
  }
  need(value.directory !== value.selectionDirectory, 'ACCOUNTING_MANAGED_PATH',
    'Keep saved company selections separate from the original accounting state.');
