}
async function sourceInput(path, type, maximumBytes = 16 * 1024 * 1024) {
  const before = await lstat(path);
  need(!before.isSymbolicLink() && (type === 'file' ? before.isFile() : before.isDirectory()) &&
    await realpath(path) === path, 'ACCOUNTING_MANAGED_INPUT_CHANGED', 'Use the original source file or directory.');
  const result = { path, type, device: String(before.dev), inode: String(before.ino) };
  if (type === 'file') {
    const handle = await open(path, constants.O_RDONLY | constants.O_NOFOLLOW);
    try {
      const first = await handle.stat();
      need(first.isFile() && first.size <= maximumBytes && first.dev === before.dev &&
        first.ino === before.ino, 'ACCOUNTING_MANAGED_INPUT_CHANGED', 'The selected accounting input changed.');
      const bytes = await handle.readFile(), after = await handle.stat();
      need(bytes.length === first.size && after.size === first.size &&
        first.mtimeMs === after.mtimeMs && first.ctimeMs === after.ctimeMs,
      'ACCOUNTING_MANAGED_INPUT_CHANGED', 'Read the current accounting source before starting.');
      result.bytes = bytes.length; result.sha256 = digest(bytes);
    } finally { await handle.close(); }
  }
  return result;
}

/** Read-only launch review; grant generation changes are retained by the original OAuth core. */
export async function inspectAccountingLaunch(raw, { env = process.env, allowMissing = false } = {}) {
  const selected = settings(raw);
  const oauth = await inspectOpenApiLaunch({
    outputParent: selected.directory, port: selected.port, oauthConnectionsFile: selected.connectionsFile,
    allowLoopbackOAuth: selected.allowLoopbackOAuth,
  }, { env, allowMissingOutput: allowMissing });
  let selections = { quickbooks: null, xero: null }, selectionRoot = null;
  if (selected.connectionsFile) {
    const root = await inspectOpenApiLaunch({ outputParent: selected.selectionDirectory, port: 0 },
      { env, allowMissingOutput: allowMissing });
    selectionRoot = root.binding.output;
    if (selectionRoot.exists) selections = await readAccountingSelections(selected.selectionDirectory);
    const sources = { quickbooks: await quickbooksSource(), xero: await xeroSource() };
    for (const provider of ['quickbooks', 'xero']) {
      const choice = selections[provider]; if (!choice) continue;
      const connection = oauth.binding.profiles.find(value => value.alias === choice.alias);
      need(connection && connection.profileSha256 === choice.profileSha256 &&
        identity(connection.source) === identity(sources[provider]) &&
        identity(choice.source) === identity(sources[provider]),
      'ACCOUNTING_MANAGED_SELECTION_CHANGED', 'The saved company or tenant must belong to this registered source and alias.');
    }
  }
  let workspaceBinding = null;
  if (oauth.binding.output.exists) {
    let original;
    try { original = await inspectAccountingWorkspaceBinding(selected.directory); }
    catch (error) { if (error.code !== 'ENOENT') throw error; }
    if (original?.sources.sourceMode === 'buyer') {
      need(['outboxDir', 'proofDir', 'termsFile', 'recoveredDir'].every(name => !selected[name]),
        'ACCOUNTING_SOURCE_AMBIGUOUS', 'This original buyer workspace already retains its issued source. Review it without merchant source paths.', 400);
      workspaceBinding = original;
    }
  }
  const inputs = [];
  if (workspaceBinding) {
    const expected = workspaceBinding.sources;
    const original = await sourceInput(expected.buyerSourceFile, 'file', 64 * 1024 * 1024);
    need(original.sha256 === expected.buyerSourceSha256 && original.bytes === expected.buyerSourceBytes,
      'ACCOUNTING_MANAGED_INPUT_CHANGED', 'The retained issued buyer source differs from this original workspace.');
    inputs.push({ name: 'buyerSourceFile', ...original });
  }
  for (const name of ['outboxDir', 'proofDir', 'recoveredDir'])
    if (selected[name]) inputs.push({ name, ...await sourceInput(selected[name], 'directory') });
  if (selected.termsFile) inputs.push({ name: 'termsFile', ...await sourceInput(selected.termsFile, 'file') });
  for (const name of ['recoveryStateRoot', 'recoveryBackupRoot']) if (selected[name]) {
    const inspected = await inspectOpenApiLaunch({ outputParent: selected[name], port: 0 }, { env });
    inputs.push({ name, type: 'directory', path: selected[name], ...inspected.binding.output });
  }
  const selectedDigests = Object.fromEntries(Object.entries(selections).map(([provider, value]) =>
    [provider, value?.integrity.sha256 ?? null]));
  const binding = { schema: ACCOUNTING_MANAGED_SCHEMA, settings: selected, oauth: oauth.binding,
    selectionRoot, selections: selectedDigests, inputs,
    ...(workspaceBinding ? { workspaceBinding } : {}) };
  return { binding, bindingSha256: identity(binding), selections,
    review: { schema: ACCOUNTING_MANAGED_SCHEMA, bindingSha256: identity(binding),
      directory: selected.directory, port: selected.port, allowLoopbackOAuth: selected.allowLoopbackOAuth,
      connectionsFile: selected.connectionsFile, selectionDirectory: selected.connectionsFile ? selected.selectionDirectory : null,
      connectionsSha256: oauth.binding.registry?.sha256 ?? null,
      profiles: oauth.review.profiles, selections: selectedDigests, inputs,
      targets: { quickbooks: selections.quickbooks ? quickBooksSelectionSummary(selections.quickbooks) : null,
        xero: selections.xero ? xeroSelectionSummary(selections.xero) : null },
      recoveryStartPaused: selected.recoveryStartPaused,
      sourceMode: workspaceBinding ? 'buyer' : 'merchant', workspaceBinding } };
}

export async function startManagedAccountingWorkspace(raw, {
  expectedSha256, startWorkspace, env = process.env, lookup, agent, fetchImpl,
  announce = value => process.stdout.write(JSON.stringify(value) + '\n'),
} = {}) {
  need(hex(expectedSha256) && typeof startWorkspace === 'function' && typeof announce === 'function',
    'ACCOUNTING_MANAGED_HOST', 'Start the original reviewed accounting host.');
  const environment = { ...env }, before = await inspectAccountingLaunch(raw, { env: environment });
  need(before.bindingSha256 === expectedSha256, 'ACCOUNTING_MANAGED_INPUT_CHANGED',
    'The registered source, saved company, accounting inputs or private directories changed. Review the current application start.');
  const selected = before.binding.settings;
  let accounting, connections, closing;
  const close = () => {
    if (!closing) {
      connections?.stop();
      closing = (async () => {
        const errors = [];
        try { await accounting?.close(); } catch (error) { errors.push(error); }
        try { await connections?.close(); } catch (error) { errors.push(error); }
        if (errors.length) throw Object.assign(new AggregateError(errors,
          'The managed accounting owners did not all close cleanly.'), { code: 'ACCOUNTING_MANAGED_CLOSE_FAILED' });
      })();
    }
    return closing;
  };
  try {
    if (selected.connectionsFile) {
      connections = await openAccountingConnections({
        connectionsFile: selected.connectionsFile, selectionDirectory: selected.selectionDirectory,
        env: environment, allowLoopback: selected.allowLoopbackOAuth,
        ...(lookup ? { lookup } : {}), ...(agent ? { agent } : {}), ...(fetchImpl ? { fetchImpl } : {}),
        origin: () => accounting?.url ?? 'http://127.0.0.1:' + selected.port,
      });
      for (const provider of ['quickbooks', 'xero'])
        need((connections.activeSelections[provider]?.integrity.sha256 ?? null) === before.binding.selections[provider],
          'ACCOUNTING_MANAGED_SELECTION_CHANGED', 'A saved company selection changed while the host was opening.');
    }
    const { connectionsFile, selectionDirectory, allowLoopbackOAuth, ...accountingOptions } = selected;
    accounting = await startWorkspace({
      ...accountingOptions,
      ...(before.binding.workspaceBinding ? {
        expectedWorkspaceId: before.binding.workspaceBinding.workspaceId,
        expectedSourcesSha256: before.binding.workspaceBinding.sourcesSha256,
      } : {}),
      ...(connections ? { qboClient: connections.qboClient, xeroClient: connections.xeroClient,
        connectionsWorkspace: connections } : {}),
    });
    const after = await inspectAccountingLaunch(selected, { env: environment });
    need(after.bindingSha256 === expectedSha256, 'ACCOUNTING_MANAGED_INPUT_CHANGED',
      'The reviewed accounting inputs changed while the original host was opening.');
    const url = new URL(accounting.url);
    need(url.protocol === 'http:' && url.hostname === '127.0.0.1' && !url.username && !url.password &&
      !url.search && !url.hash && url.pathname === '/' &&
      (selected.port === 0 || Number(url.port) === selected.port),
    'ACCOUNTING_MANAGED_STARTUP', 'Use the original local accounting address.');
    const startup = {
      schema: ACCOUNTING_STARTUP_SCHEMA, status: 'ACCOUNTING_WORKSPACE_READY',
      instanceId: randomUUID(), pid: process.pid, startedAt: new Date().toISOString(),
      directory: selected.directory, selectionDirectory: connections ? selected.selectionDirectory : null,
      requestedPort: selected.port, port: Number(url.port), bindingSha256: expectedSha256,
      connectionsFile: selected.connectionsFile,
      connectionsSha256: before.binding.oauth.registry?.sha256 ?? null,
      profileCount: before.binding.oauth.profiles.length, selections: before.binding.selections,
      url: accounting.url, connectionsUrl: connections ? accounting.url + '/connections.html' : null,
      ...(before.binding.workspaceBinding ? { workspaceBinding: before.binding.workspaceBinding } : {}),
    };
    await announce(startup);
    return Object.freeze({ accounting, connections, managed: startup, url: accounting.url, close });
  } catch (error) { await close().catch(() => {}); throw error; }
}

const argumentNames = Object.freeze({
  '--workspace': 'directory', '--port': 'port', '--oauth-connections': 'connectionsFile',
  '--connection-selections': 'selectionDirectory', '--outbox': 'outboxDir', '--proof-dir': 'proofDir',
  '--terms': 'termsFile', '--recovered-dir': 'recoveredDir', '--rpc-proxy-env': 'rpcProxyEnv',
  '--recovery-state-root': 'recoveryStateRoot', '--recovery-backup-root': 'recoveryBackupRoot',
  '--recovery-pass-env': 'recoveryPassEnv', '--delivery-secret-env': 'deliverySecretEnv',
});
export function accountingManagedArguments(raw) {
  need(Array.isArray(raw), 'ACCOUNTING_MANAGED_ARGUMENTS', 'Use the original managed accounting command.', 400);
  const values = {}, seen = new Set(); let expectedSha256;
  for (let index = 0; index < raw.length; index++) {
    const name = raw[index];
    need(typeof name === 'string' && !seen.has(name), 'ACCOUNTING_MANAGED_ARGUMENTS',
      'Each accounting launch option appears once.', 400); seen.add(name);
    if (name === '--allow-loopback-oauth') { values.allowLoopbackOAuth = true; continue; }
    if (name === '--recovery-start-paused') { values.recoveryStartPaused = true; continue; }
    need((Object.hasOwn(argumentNames, name) || name === '--managed-launch-sha256') &&
      typeof raw[index + 1] === 'string' && raw[index + 1] && !raw[index + 1].startsWith('--'),
    'ACCOUNTING_MANAGED_ARGUMENTS', 'Use the exact reviewed accounting launch arguments.', 400);
    const value = raw[++index];
    if (name === '--managed-launch-sha256') expectedSha256 = value;
    else values[argumentNames[name]] = name === '--port' ? Number(value) : value;
  }
  need(hex(expectedSha256), 'ACCOUNTING_MANAGED_ARGUMENTS', 'Keep the reviewed accounting launch digest.', 400);
  return { settings: settings(values), expectedSha256 };
}

// MIT. Immutable recorded-activity definitions and retained closes over native runs.
import {createHash,randomUUID} from 'node:crypto';
import {constants} from 'node:fs';
import {open} from 'node:fs/promises';
import {join} from 'node:path';
import {compileAccountingPeriod} from '../reconcile.mjs';

const now=()=>new Date().toISOString();
const hash=bytes=>createHash('sha256').update(bytes).digest('hex');
const check=(ok,code,message,status=400)=>{if(!ok)throw Object.assign(new Error(message),{code,status});};
const label=(value,name,max=160,empty=false)=>{
  check(typeof value==='string'&&(empty||value.trim().length>0)&&value.trim().length<=max,'INVALID_FIELD','Check '+name+'.');
  return value.trim();
};
const same=(a,b)=>JSON.stringify(a)===JSON.stringify(b);
const page=query=>{
  const offset=Number(query.offset??0),limit=Number(query.limit??50);
  check(Number.isSafeInteger(offset)&&offset>=0&&Number.isSafeInteger(limit)&&limit>=1&&limit<=200,'INVALID_PAGE','Use a nonnegative offset and up to 200 rows.');
  return {offset,limit};
};
const emptyReview=()=>({status:'open',note:'',assignee:'',actor:'',version:0,updatedAt:null});
const counts=rows=>rows.reduce((result,row)=>{result[row.review.status]++;return result;},{open:0,investigating:0,reviewed:0});

export class PeriodWorkspace{
  constructor(workspace){this.workspace=workspace;}
  view(){const state=this.workspace.state;return {definitions:state.periodDefinitions??[],selection:state.periodSelection??null,closes:state.periodCloses??[]};}
  definition(id){const record=this.workspace.state.periodDefinitions.find(item=>item.id===id);check(record,'PERIOD_NOT_FOUND','Choose a saved recorded-activity period.',404);return record;}
  selection(value=this.workspace.state.periodSelection){
    if(value===null||value===undefined)return null;
    check(value&&typeof value==='object'&&!Array.isArray(value)&&Number.isSafeInteger(value.version),'INVALID_PERIOD_SELECTION','Choose a saved period version.');
    const record=this.definition(value.id),version=record.versions.find(item=>item.version===value.version);
    check(version,'PERIOD_VERSION_NOT_FOUND','Choose an existing saved period version.',404);
    return {periodId:record.id,version:version.version,name:version.name,from:version.from,until:version.until};
  }
  async save({revision,id,expectedVersion,name,from,until,note='',select=false,actor}){
    const workspace=this.workspace;
    return workspace.serial(async()=>{
      workspace.expected(revision);actor=label(actor,'operator',1000);name=label(name,'period name');note=label(note,'period note',2000,true);
      check(typeof select==='boolean','INVALID_PERIOD_SELECTION','Choose whether to select the saved version.');
      const bounds=compileAccountingPeriod({from,until});
      let record=id?this.definition(id):null;
      if(record){
        check(expectedVersion===record.versions.at(-1).version,'STALE_PERIOD','The saved definition changed. Reload its current version before retaining your edited definition.',409);
        check(record.versions.length<1000,'PERIOD_VERSION_LIMIT','This period already retains 1,000 definitions.');
      }else{
        check(workspace.state.periodDefinitions.length<1000,'PERIOD_LIMIT','This workspace already retains 1,000 named periods.');
        record={id:randomUUID(),createdAt:now(),actor,versions:[]};workspace.state.periodDefinitions.unshift(record);
      }
      const version={version:record.versions.length+1,name,...bounds,note,actor,createdAt:now()};
      record.versions.push(version);
      if(select)workspace.state.periodSelection={id:record.id,version:version.version};
      await workspace.commit('accounting_period_saved',actor,{periodId:record.id,version:version.version,from:bounds.from,until:bounds.until,selected:select});
      return {definition:structuredClone(record),version:structuredClone(version),state:workspace.view()};
    });
  }
  async select({revision,selection,actor}){
    const workspace=this.workspace;
    return workspace.serial(async()=>{
      workspace.expected(revision);actor=label(actor,'operator',1000);
      const chosen=this.selection(selection),value=chosen?{id:chosen.periodId,version:chosen.version}:null;
      if(!same(value,workspace.state.periodSelection)){
        workspace.state.periodSelection=value;
        await workspace.commit('accounting_period_selected',actor,{selection:value});
      }
      return workspace.view();
    });
  }
  closeRow(id){const row=this.workspace.state.periodCloses.find(item=>item.id===id);check(row,'PERIOD_CLOSE_NOT_FOUND','Choose a retained period close.',404);return row;}
  async retainClose({revision,runId,name,note='',includeSources=true,actor}){
    const workspace=this.workspace;
    return workspace.serial(async()=>{
      workspace.expected(revision);actor=label(actor,'operator',1000);name=label(name,'close name');note=label(note,'close note',4000,true);
      check(typeof includeSources==='boolean','INVALID_EXPORT','Choose whether the archive includes the retained original source files.');
      const run=workspace.runRow(runId),report=await workspace.report(runId);
      check(run.period&&report.period,'PERIOD_RUN_REQUIRED','Choose a completed run captured with a saved recorded-activity period.');
      check(workspace.state.periodCloses.length<5000,'PERIOD_CLOSE_LIMIT','This workspace already retains 5,000 closes.');
      const prior=workspace.state.periodCloses.find(item=>item.period.periodId===run.period.periodId);
      const close={schema:'stellar-forge.merchant-period-close.v1',id:randomUUID(),revision:(prior?.revision??0)+1,
        previousCloseId:prior?.id??null,name,note,actor,createdAt:now(),period:structuredClone(run.period),scope:report.period};
      // The existing writer freezes the original report, sources, and reviews.
      // Open/investigating exceptions are retained, never converted or suppressed.
      const retained=await workspace.retainExport(runId,{actor,includeSources,close});
      workspace.state.periodCloses.unshift(retained.close);
      await workspace.commit('accounting_period_closed',actor,{closeId:close.id,closeRevision:close.revision,periodId:run.period.periodId,
        periodVersion:run.period.version,runId,exportId:retained.export.id,reviewCounts:retained.close.reviewCounts});
      return {...retained,state:workspace.view()};
    });
  }
  async file(id,name){
    const close=this.closeRow(id),keys={'period-close.json':'closeSha256','review-notes.json':'reviewNotesSha256'};
    const adjustment=['adjustments.json','adjustments.csv','adjustments.html'].includes(name)?close.adjustmentFiles?.[name]:null;
    const expected=adjustment?.sha256??(name==='adjustments.json'?close.adjustmentsSha256:close[keys[name]]);
    check((Object.hasOwn(keys,name)||adjustment||name==='adjustments.json')&&expected,'CLOSE_FILE_NOT_FOUND','Choose the original close metadata, frozen review notes or retained adjustments.',404);
    const path=join(this.workspace.directory,'exports',close.exportId,name),handle=await open(path,constants.O_RDONLY|(constants.O_NOFOLLOW??0));
    let bytes;
    try{const info=await handle.stat();check(info.isFile()&&info.size>0&&info.size<=128_000_000,'CLOSE_FILE_CHANGED','The retained close file changed.',409);bytes=await handle.readFile();}
    finally{await handle.close();}
    check(hash(bytes)===expected&&(adjustment?.bytes===undefined||bytes.length===adjustment.bytes),'CLOSE_FILE_CHANGED','The retained close file changed.',409);
    return {bytes,name};
  }
  async detail(id){
    const close=structuredClone(this.closeRow(id));await this.file(id,'period-close.json');
    const snapshot=JSON.parse((await this.file(id,'review-notes.json')).bytes.toString('utf8'));
    const current=snapshot.exceptions.map(row=>({...row,review:this.workspace.state.notes[row.id]??emptyReview()}));
