}
const required=(options,key)=>{need(typeof options[key]==='string'&&options[key].trim(),'SOURCE_CHANGE_ARGUMENTS','Provide '+key+'.');return options[key];};
function endpoint(value){
  let url;try{url=new URL(value);}catch{}
